import fs from 'fs';
const src = fs.readFileSync('/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/u35/game.html', 'utf8');
const m = src.match(/<script>([\s\S]*)<\/script>/);
if (!m) { console.log('NO SCRIPT BLOCK'); process.exit(1); }
const js = m[1];

// 1) full-file syntax check (parse only, never executed — UI code needs a DOM)
try { new Function(js); console.log('FULL SYNTAX OK'); }
catch (e) { console.log('FULL SYNTAX FAIL: ' + e.message); process.exit(1); }

// 2) execute the engine-only portion and expose its functions for testing
const cut = js.indexOf('let G=newGame(1337);');
if (cut < 0) { console.log('UI marker not found'); process.exit(1); }
const engine = js.slice(0, cut) + `
;globalThis.__api = { newGame, endTurn, policyStep, policyChoice, applyChoice, runTests,
  runBenchmark, hashState, serialize, deserialize, popOf, capsOf, RESKEYS, simTurns };
`;
try { new Function(engine)(); console.log('ENGINE EXEC OK'); }
catch (e) { console.log('ENGINE EXEC FAIL: ' + e.stack); process.exit(1); }
const api = globalThis.__api;

// 3) run the built-in test suite
const t = api.runTests();
console.log(t.text);
if (t.fail > 0) process.exit(1);

// 4) benchmark determinism: run twice, hashes must match
const b1 = api.runBenchmark(1337);
const b2 = api.runBenchmark(1337);
console.log(b1);
console.log('BENCH REPRODUCIBLE: ' + (b1 === b2));
if (b1 !== b2) process.exit(1);

// 5) sanity: is the game winnable/losable under scripted play?
//    a) losable: idle play (never build/assign) should collapse
{
  const S = api.newGame(1337);
  for (let i = 0; i < 80 && !S.over; i++) { api.endTurn(S, true); if (S.pending) api.applyChoice(S, 1); }
  console.log('IDLE RUN: over=' + !!S.over + ' win=' + (S.over && S.over.win) + ' pop=' + api.popOf(S) + ' turn=' + S.turn);
}
//    b) greedy policy outcomes across several seeds
for (const seed of [1337, 7, 99, 2024, 555]) {
  const S = api.newGame(seed);
  for (let i = 0; i < 60 && !S.over; i++) {
    api.policyStep(S); api.endTurn(S, true);
    if (S.pending) api.applyChoice(S, api.policyChoice(S));
  }
  console.log('SEED ' + seed + ': ' + (S.over ? (S.over.win ? 'WIN' : 'LOSS') + ' score ' + S.over.score : 'no end') +
    ' pop=' + api.popOf(S) + ' turn=' + S.turn);
}
console.log('ALL VERIFICATION DONE');
